-- Add a reusable 150-sentence situational deck with highlighted vocabulary and audio.
insert into public.template_decks (slug, name, description, level)
values (
  'xuat-nhap-khau-logistics-150-cau',
  'Xuất nhập khẩu và logistics - 150 câu',
  '150 câu tiếng Trung thực tế cho xuất nhập khẩu và logistics: tìm nguồn hàng, hợp đồng, Incoterms, thanh toán, chứng từ, hải quan, kho bãi, vận tải, giao nhận và xử lý sự cố. Mỗi câu có pinyin, nghĩa tiếng Việt, 1-2 từ mới được highlight và audio tạo sẵn.',
  'Luyện câu'
)
on conflict (slug) do update
set name = excluded.name, description = excluded.description, level = excluded.level;

with target_deck as (
  select id from public.template_decks where slug = 'xuat-nhap-khau-logistics-150-cau'
)
insert into public.template_sentence_cards (
  template_deck_id, sentence_cn, sentence_pinyin, sentence_vi,
  vocab_json, sentence_audio_url, position
)
select
  target_deck.id, card.sentence_cn, card.sentence_pinyin,
  card.sentence_vi, card.vocab_json::jsonb,
  card.sentence_audio_url, card.position
from target_deck
cross join (
  values
    ('请提供贵公司的产品目录供我们参考。', 'Qǐng tígōng guì gōngsī de chǎnpǐn mùlù gōng wǒmen cānkǎo.', 'Vui lòng cung cấp danh mục sản phẩm của quý công ty để chúng tôi tham khảo.', '[{"chinese":"产品目录","pinyin":"chǎnpǐn mùlù","meaning_vi":"danh mục sản phẩm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-946343cf3eda75c506030cdb.mp3', 1),
    ('请发送贵公司的最新报价单，以便我们评估成本。', 'Qǐng fāsòng guì gōngsī de zuìxīn bàojiàdān，yǐbiàn wǒmen pínggū chéngběn.', 'Vui lòng gửi bảng báo giá mới nhất của quý công ty để chúng tôi đánh giá chi phí.', '[{"chinese":"报价单","pinyin":"bàojiàdān","meaning_vi":"bảng báo giá"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-23fa9085c854a1a34c2a697b.mp3', 2),
    ('请问贵公司的产品最小起订量是多少？', 'Qǐngwèn guì gōngsī de chǎnpǐn zuìxiǎo qǐdìngliàng shì duōshǎo？', 'Xin hỏi số lượng đặt tối thiểu sản phẩm của quý công ty là bao nhiêu?', '[{"chinese":"最小起订量","pinyin":"zuìxiǎo qǐdìngliàng","meaning_vi":"số lượng đặt tối thiểu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-16b5a326139ea19dacc662b7.mp3', 3),
    ('能否提供产品的样品供我们质量评估？', 'Néngfǒu tígōng chǎnpǐn de yàngpǐn gōng wǒmen zhìliàng pínggū？', 'Có thể cung cấp mẫu sản phẩm để chúng tôi đánh giá chất lượng không?', '[{"chinese":"样品","pinyin":"yàngpǐn","meaning_vi":"mẫu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-2ec6984a8f0f000c4b26bbcb.mp3', 4),
    ('请确认产品的规格是否符合我们的要求。', 'Qǐng quèrèn chǎnpǐn de guīgé shìfǒu fúhé wǒmen de yāoqiú.', 'Vui lòng xác nhận quy cách sản phẩm có phù hợp với yêu cầu của chúng tôi không.', '[{"chinese":"规格","pinyin":"guīgé","meaning_vi":"quy cách"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-b794879492cdf14b2142ddd5.mp3', 5),
    ('贵公司具有充足的供货能力满足我们的采购需求吗？', 'Guì gōngsī jùyǒu chōngzú de gōnghuò nénglì mǎnzú wǒmen de cǎigòu xūqiú ma？', 'Công ty quý bên có đủ năng lực cung ứng để đáp ứng nhu cầu mua hàng của chúng tôi không?', '[{"chinese":"供货能力","pinyin":"gōnghuò nénglì","meaning_vi":"năng lực cung ứng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-04a7b1d9d1e370ca61aa85bf.mp3', 6),
    ('请告知产品的生产周期，以便安排采购计划。', 'Qǐng gàozhī chǎnpǐn de shēngchǎn zhōuqī，yǐbiàn ānpái cǎigòu jìhuà.', 'Vui lòng cho biết thời gian sản xuất sản phẩm để sắp xếp kế hoạch mua hàng.', '[{"chinese":"生产周期","pinyin":"shēngchǎn zhōuqī","meaning_vi":"thời gian sản xuất"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-e4d0d77c9f12b9b39b248559.mp3', 7),
    ('请确认我们计划订购的数量是否可以按期供应。', 'Qǐng quèrèn wǒmen jìhuà dìnggòu de shùliàng shìfǒu kěyǐ ànqī gōngyìng.', 'Vui lòng xác nhận số lượng chúng tôi dự kiến đặt có thể được cung ứng đúng hạn hay không.', '[{"chinese":"按期供应","pinyin":"ànqī gōngyìng","meaning_vi":"cung ứng đúng hạn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-7fccba06a345457c390cfb5a.mp3', 8),
    ('请根据实际情况调整本次的采购订单内容。', 'Qǐng gēnjù shíjì qíngkuàng tiáozhěng běncì de cǎigòu dìngdān nèiróng.', 'Vui lòng điều chỉnh nội dung đơn mua hàng lần này theo tình hình thực tế.', '[{"chinese":"采购订单","pinyin":"cǎigòu dìngdān","meaning_vi":"đơn mua hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-59d698c5768778bc6fb28db4.mp3', 9),
    ('请提供订单的最新备货进度以便我们跟踪。', 'Qǐng tígōng dìngdān de zuìxīn bèihuò jìndù yǐbiàn wǒmen gēnzōng.', 'Vui lòng cung cấp tiến độ chuẩn bị hàng mới nhất của đơn để chúng tôi theo dõi.', '[{"chinese":"备货进度","pinyin":"bèihuò jìndù","meaning_vi":"tiến độ chuẩn bị hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-fe1190732dd98e9c90a8dd82.mp3', 10),
    ('请在下单前确认产品的质量标准符合合同要求。', 'Qǐng zài xià dān qián quèrèn chǎnpǐn de zhìliàng biāozhǔn fúhé hétóng yāoqiú.', 'Vui lòng xác nhận tiêu chuẩn chất lượng sản phẩm trước khi đặt hàng đáp ứng yêu cầu hợp đồng.', '[{"chinese":"质量标准","pinyin":"zhìliàng biāozhǔn","meaning_vi":"tiêu chuẩn chất lượng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-ae2e65b44f844a39d9d02b9b.mp3', 11),
    ('请尽快审批本次的采购订单以确保生产进度。', 'Qǐng jǐnkuài shěnpī běncì de cǎigòu dìngdān yǐ quèbǎo shēngchǎn jìndù.', 'Vui lòng phê duyệt nhanh đơn mua hàng này để đảm bảo tiến độ sản xuất.', '[{"chinese":"审批","pinyin":"shěnpī","meaning_vi":"phê duyệt"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-b1339aeb85fb4ab9f2cda3de.mp3', 12),
    ('请评估供应商的生产能力是否满足我们的需求。', 'Qǐng pínggū gōngyìngshāng de shēngchǎn nénglì shìfǒu mǎnzú wǒmen de xūqiú.', 'Xin đánh giá năng lực sản xuất của nhà cung cấp có đáp ứng nhu cầu của chúng tôi không.', '[{"chinese":"生产能力","pinyin":"shēngchǎn nénglì","meaning_vi":"năng lực sản xuất"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-5929dd7f69d3e0d675fe09a8.mp3', 13),
    ('请确认是否可以提供产品的技术参数详情。', 'Qǐng quèrèn shìfǒu kěyǐ tígōng chǎnpǐn de jìshù cānshù xiángqíng.', 'Vui lòng xác nhận có thể cung cấp chi tiết thông số kỹ thuật sản phẩm không.', '[{"chinese":"技术参数","pinyin":"jìshù cānshù","meaning_vi":"thông số kỹ thuật"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-54cf1011d487fb202becd8fe.mp3', 14),
    ('请注明最小起订量及相应的包装规格。', 'Qǐng zhùmíng zuìxiǎo qǐdìngliàng jí xiāngyìng de bāozhuāng guīgé.', 'Vui lòng ghi rõ số lượng đặt tối thiểu và quy cách đóng gói tương ứng.', '[{"chinese":"包装规格","pinyin":"bāozhuāng guīgé","meaning_vi":"quy cách đóng gói"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-a0ffb57b1ef9ce57d656c9a4.mp3', 15),
    ('请提供贵司的生产设备详情以供参考。', 'Qǐng tígōng guì sī de shēngchǎn shèbèi xiángqíng yǐ gōng cānkǎo.', 'Vui lòng cung cấp chi tiết về thiết bị sản xuất của quý công ty để tham khảo.', '[{"chinese":"生产设备","pinyin":"shēngchǎn shèbèi","meaning_vi":"thiết bị sản xuất"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-0e6e1d1106e38970b7d05184.mp3', 16),
    ('请问产品的定制周期一般需要多长时间？', 'Qǐngwèn chǎnpǐn de dìngzhì zhōuqī yībān xūyào duō cháng shíjiān？', 'Xin hỏi thời gian gia công đặt hàng sản phẩm thường mất bao lâu?', '[{"chinese":"定制周期","pinyin":"dìngzhì zhōuqī","meaning_vi":"thời gian gia công đặt hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-9f3c5bf37dc835916e3ee884.mp3', 17),
    ('我们希望确认货物的交货时间以便合理安排。', 'Wǒmen xīwàng quèrèn huòwù de jiāohuò shíjiān yǐbiàn hélǐ ānpái.', 'Chúng tôi muốn xác nhận thời gian giao hàng để sắp xếp hợp lý.', '[{"chinese":"交货时间","pinyin":"jiāohuò shíjiān","meaning_vi":"thời gian giao hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-33b4fe3cd5954d65e13c7466.mp3', 18),
    ('请告知是否支持小批量订单生产。', 'Qǐng gàozhī shìfǒu zhīchí xiǎo pīliàng dìngdān shēngchǎn.', 'Vui lòng cho biết có hỗ trợ sản xuất các đơn hàng số lượng nhỏ không.', '[{"chinese":"订单","pinyin":"dìngdān","meaning_vi":"đơn hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-5cdd9ba04eb8cc0f5f72656c.mp3', 19),
    ('请确认产品的保质期符合进口要求。', 'Qǐng quèrèn chǎnpǐn de bǎozhìqī fúhé jìnkǒu yāoqiú.', 'Vui lòng xác nhận hạn dùng sản phẩm phù hợp yêu cầu nhập khẩu.', '[{"chinese":"保质期","pinyin":"bǎozhìqī","meaning_vi":"hạn dùng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-3118e822f0ecb77981d51aad.mp3', 20),
    ('请提供最新的产品认证证书以供审核。', 'Qǐng tígōng zuìxīn de chǎnpǐn rènzhèng zhèngshū yǐ gōng shěnhé.', 'Vui lòng cung cấp giấy chứng nhận sản phẩm mới nhất để chúng tôi kiểm tra.', '[{"chinese":"认证证书","pinyin":"rènzhèng zhèngshū","meaning_vi":"giấy chứng nhận"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-ca63633896f29f48247059cc.mp3', 21),
    ('请提供贵公司的付款条件和相关流程。', 'Qǐng tígōng guì gōngsī de fùkuǎn tiáojiàn hé xiāngguān liúchéng.', 'Vui lòng cung cấp điều kiện thanh toán và quy trình liên quan của quý công ty.', '[{"chinese":"条件","pinyin":"tiáojiàn","meaning_vi":"điều kiện"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-fa1879bc1fbe28904215b7a3.mp3', 22),
    ('请说明是否可以接受订单的修改请求。', 'Qǐng shuōmíng shìfǒu kěyǐ jiēshòu dìngdān de xiūgǎi qǐngqiú.', 'Vui lòng cho biết có thể chấp nhận yêu cầu chỉnh sửa đơn hàng không.', '[{"chinese":"修改请求","pinyin":"xiūgǎi qǐngqiú","meaning_vi":"yêu cầu chỉnh sửa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-0888816482e21014dbd3b426.mp3', 23),
    ('请确认最终交期是否符合我们的采购计划。', 'Qǐng quèrèn zuìzhōng jiāoqī shìfǒu fúhé wǒmen de cǎigòu jìhuà.', 'Vui lòng xác nhận ngày giao hàng cuối cùng có phù hợp với kế hoạch mua hàng của chúng tôi không.', '[{"chinese":"采购计划","pinyin":"cǎigòu jìhuà","meaning_vi":"kế hoạch mua hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-8d3638e86d519f6bf9d91397.mp3', 24),
    ('请提供贵方的质量检验报告以便我们审核。', 'Qǐng tígōng guì fāng de zhìliàng jiǎnyàn bàogào yǐbiàn wǒmen shěnhé.', 'Xin cung cấp báo cáo kiểm tra chất lượng của quý công ty để chúng tôi rà soát.', '[{"chinese":"质量检验报告","pinyin":"zhìliàng jiǎnyàn bàogào","meaning_vi":"báo cáo kiểm tra chất lượng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-d1e929e6189a9b93be0593a4.mp3', 25),
    ('请确认合同中约定的支付方式是电汇还是信用证。', 'Qǐng quèrèn hé​tóng zhōng yuēdìng de zhīfù fāngshì shì diànhuì háishì xìnyòngzhèng.', 'Xin xác nhậnphương thức thanh toántrong hợp đồng là chuyển khoản hay thư tín dụng.', '[{"chinese":"支付方式","pinyin":"zhīfù fāngshì","meaning_vi":"phương thức thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-7e2a6e78096ac72b38fae14b.mp3', 26),
    ('请提供本次交易的货币种类，以便我们安排结算。', 'Qǐng tígōng běncì jiāoyì de huòbì zhǒnglèi， yǐbiàn wǒmen ānpái jiésuàn.', 'Vui lòng cung cấploại tiền tệcủa giao dịch này để chúng tôi sắp xếp thanh toán.', '[{"chinese":"货币种类","pinyin":"huòbì zhǒnglèi","meaning_vi":"loại tiền tệ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-57bfbf48884216536e3177e1.mp3', 27),
    ('合同中规定的交货期限是收到定金后三十天。', 'Hétóng zhōng guīdìng de jiāohuò qīxiàn shì shōudào dìngjīn hòu sānshí tiān.', 'Thời hạn giao hàngđược quy địnhtrong hợp đồng là 30 ngày kể từ khi nhận đặt cọc.', '[{"chinese":"交货期限","pinyin":"jiāohuò qīxiàn","meaning_vi":"thời hạn giao hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-e31f1ca638fe9c393c719cf7.mp3', 28),
    ('请确认合同的价格条款是否包含运输费用。', 'Qǐng quèrèn hétóng de jiàgé tiáokuǎn shìfǒu bāohán yùnshū fèiyòng.', 'Xin xác nhậnđiều khoản giátrong hợp đồng có bao gồm chi phí vận chuyển không.', '[{"chinese":"价格条款","pinyin":"jiàgé tiáokuǎn","meaning_vi":"điều khoản giá"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-1fd5f612fe077af57b87920b.mp3', 29),
    ('请提供开立信用证所需的全部合同资料。', 'Qǐng tígōng kāilì xìnyòngzhèng suǒ xū de quánbù hétóng zīliào.', 'Vui lòng cung cấp đầy đủ tài liệu hợp đồng để mởthư tín dụng.', '[{"chinese":"信用证","pinyin":"xìnyòngzhèng","meaning_vi":"thư tín dụng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-6b337994e8521b712034df3d.mp3', 30),
    ('请支付订单金额的三成作为定金，剩余部分按合同付款。', 'Qǐng zhīfù dìngdān jīn''é de sān chéng zuòwéi dìngjīn， shèngyú bùfèn àn hétóng fùkuǎn.', 'Vui lòng thanh toán 30% giá trị đơn hàng làmđặt cọc, số còn lại thanh toán theo hợp đồng.', '[{"chinese":"定金","pinyin":"dìngjīn","meaning_vi":"đặt cọc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-ad7ff201cf3842888ea8639d.mp3', 31),
    ('请确认收款账户名称和银行信息以便安全转账。', 'Qǐng quèrèn shōukuǎn zhànghù míngchēng hé yínháng xìnxī yǐbiàn ānquán zhuǎnzhàng.', 'Xin xác nhận tên tài khoản nhận tiền và thông tin ngân hàng để chuyển khoản an toàn.', '[{"chinese":"账户","pinyin":"zhànghù","meaning_vi":"tài khoản"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-f620bf214a1263999025fe63.mp3', 32),
    ('请确认付款期限是否满足合同约定要求。', 'Qǐng quèrèn fùkuǎn qīxiàn shìfǒu mǎnzú hétóng yuēdìng yāoqiú.', 'Xin xác nhận thời hạn thanh toán có đáp ứng yêu cầu trong hợp đồng không.', '[{"chinese":"付款期限","pinyin":"fùkuǎn qīxiàn","meaning_vi":"thời hạn thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-b496e29308e5131f8bca8fc0.mp3', 33),
    ('请提供卖方的银行信息以便开立信用证。', 'Qǐng tígōng màifāng de yínháng xìnxī yǐbiàn kāilì xìnyòngzhèng.', 'Vui lòng cung cấp thông tin ngân hàng bên bán để mởthư tín dụng.', '[{"chinese":"信用证","pinyin":"xìnyòngzhèng","meaning_vi":"thư tín dụng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-997d9a4fa707c15b87ccf410.mp3', 34),
    ('请确认合同中关于货物风险转移的条款内容。', 'Qǐng quèrèn hétóng zhōng guānyú huòwù fēngxiǎn zhuǎnyí de tiáokuǎn nèiróng.', 'Xin xác nhận nội dung điều khoản vềchuyển giao rủi ro hàng hóatrong hợp đồng.', '[{"chinese":"货物风险转移","pinyin":"huòwù fēngxiǎn zhuǎnyí","meaning_vi":"chuyển giao rủi ro hàng hóa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-bcba58519107d1ff92b33e08.mp3', 35),
    ('合同约定买方承担所有出口报关费用。', 'Hétóng yuēdìng mǎifāng chéngdān suǒyǒu chūkǒu bàoguān fèiyòng.', 'Hợp đồng quy định bên mua chịu toàn bộ chi phí khai báo hải quan xuất khẩu.', '[{"chinese":"出口报关费用","pinyin":"chūkǒu bàoguān fèiyòng","meaning_vi":"chi phí khai báo hải quan xuất khẩu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-ceb95cff68d27a4a8cca7424.mp3', 36),
    ('请问是否支持部分货款以现金形式支付？', 'Qǐngwèn shìfǒu zhīchí bùfèn huòkuǎn yǐ xiànjīn xíngshì zhīfù?', 'Xin hỏi có hỗ trợ thanh toán một phần tiền hàng bằng tiền mặt không?', '[{"chinese":"现金","pinyin":"xiànjīn","meaning_vi":"tiền mặt"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-8c8e775a3e1a82f92b4c826c.mp3', 37),
    ('请您尽快确认订单总金额和付款计划。', 'Qǐng nín jǐnkuài quèrèn dìngdān zǒng jīn''é hé fùkuǎn jìhuà.', 'Mong quý vị sớm xác nhận tổng giá trị đơn hàng và kế hoạch thanh toán.', '[{"chinese":"付款计划","pinyin":"fùkuǎn jìhuà","meaning_vi":"kế hoạch thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-3b68136cf1baf1eb98e7f622.mp3', 38),
    ('请提供含税和未含税的价格明细表。', 'Qǐng tígōng hán shuì hé wèi hán shuì de jiàgé míngxì biǎo.', 'Vui lòng cung cấpbảng chi tiết giácó thuế và chưa thuế.', '[{"chinese":"价格明细表","pinyin":"jiàgé míngxì biǎo","meaning_vi":"bảng chi tiết giá"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-632e3740f68d2b359e1ba046.mp3', 39),
    ('根据合同，卖方负责为货物投保合理的货物保险。', 'Gēnjù hétóng, màifāng fùzé wèi huòwù tóubǎo hélǐ de huòwù bǎoxiǎn.', 'Theo hợp đồng, bên bán chịu trách nhiệm muabảo hiểm hàng hóahợp lý.', '[{"chinese":"货物保险","pinyin":"huòwù bǎoxiǎn","meaning_vi":"bảo hiểm hàng hóa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-ce4a60bc0d9b974824b90ae6.mp3', 40),
    ('请确认信用证开具的有效期和相关条件。', 'Qǐng quèrèn xìnyòngzhèng kāijù de yǒuxiàoqī hé xiāngguān tiáojiàn.', 'Xin xác nhận thời hạn hiệu lực và các điều kiện liên quan của thư tín dụng.', '[{"chinese":"有效期","pinyin":"yǒuxiàoqī","meaning_vi":"thời hạn hiệu lực"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-2c8554d0815726254ad0c5e0.mp3', 41),
    ('请说明是否可以接受合同条款的部分修改。', 'Qǐng shuōmíng shìfǒu kěyǐ jiēshòu hétóng tiáokuǎn de bùfen xiūgǎi.', 'Vui lòng cho biết có thể chấp nhận sửa đổi một phần điều khoản hợp đồng không.', '[{"chinese":"合同条款","pinyin":"hétóng tiáokuǎn","meaning_vi":"điều khoản hợp đồng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-289381d712e48336ac3f31db.mp3', 42),
    ('请确认订单需要的预付款比例和支付时间。', 'Qǐng quèrèn dìngdān xūyào de yùfùkuǎn bǐlì hé zhīfù shíjiān.', 'Xin xác nhận tỷ lệ và thời gian thanh toántiền đặt trướccủa đơn hàng.', '[{"chinese":"预付款","pinyin":"yùfùkuǎn","meaning_vi":"tiền đặt trước"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-9750501978a1c991f2a4878f.mp3', 43),
    ('合同明确买方承担部分进口税费和相关费用。', 'Hétóng míngquè mǎifāng chéngdān bùfen jìnkǒu shuìfèi hé xiāngguān fèiyòng.', 'Hợp đồng quy định bên mua chịu một phần thuế nhập khẩu và chi phí liên quan.', '[{"chinese":"进口税费","pinyin":"jìnkǒu shuìfèi","meaning_vi":"thuế nhập khẩu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-3244d56cf0dcf34d3559ae87.mp3', 44),
    ('请您提供合同附件中的付款证明文件。', 'Qǐng nín tígōng hétóng fùjiàn zhōng de fùkuǎn zhèngmíng wénjiàn.', 'Vui lòng cung cấpchứng từ thanh toánđính kèm trong hợp đồng.', '[{"chinese":"付款证明","pinyin":"fùkuǎn zhèngmíng","meaning_vi":"chứng từ thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-85aa2f4611bcb66f8474d900.mp3', 45),
    ('请问定金支付后，是否才能启动生产流程？', 'Qǐngwèn dìngjīn zhīfù hòu, shìfǒu cáinéng qǐdòng shēngchǎn liúchéng?', 'Xin hỏi sau khi thanh toán đặt cọc mới bắt đầu được quy trình sản xuất phải không?', '[{"chinese":"定金","pinyin":"dìngjīn","meaning_vi":"đặt cọc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-16a4df7e423600a892d0e700.mp3', 46),
    ('请确认买卖双方的结算周期具体安排。', 'Qǐng quèrèn mǎimài shuāngfāng de jiésuàn zhōuqī jùtǐ ānpái.', 'Xin xác nhậnchu kỳ thanh toángiữa hai bên mua bán cụ thể như thế nào.', '[{"chinese":"结算周期","pinyin":"jiésuàn zhōuqī","meaning_vi":"chu kỳ thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-01e74d763d5da34a0c69013d.mp3', 47),
    ('根据合同条款，风险在货物装船时转移给买方。', 'Gēnjù hétóng tiáokuǎn, fēngxiǎn zài huòwù zhuāngchuán shí zhuǎnyí gěi mǎifāng.', 'Theo điều khoản hợp đồng, rủi ro sẽ chuyển giao cho bên mua khi hàng được xếp lên tàu.', '[{"chinese":"装船","pinyin":"zhuāngchuán","meaning_vi":"xếp hàng lên tàu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-cb499be71e58bfcc28caf347.mp3', 48),
