    ('请确认产品的HS编码是否准确无误。', 'Qǐng quèrèn chǎnpǐn de HS biānmǎ shìfǒu zhǔnquè wúwù.', 'Vui lòng xác nhận mã HS của sản phẩm có chính xác hay không.', '[{"chinese":"HS编码","pinyin":"HS biānmǎ","meaning_vi":"mã HS"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-66dcae084f072f52306320d6.mp3', 76),
    ('请按要求如实填写货物的海关申报价值。', 'Qǐng àn yāoqiú rúshí tiánxiě huòwù de hǎiguān shēnbào jiàzhí.', 'Vui lòng khai báo trị giá hải quan của hàng hóa một cách trung thực theo yêu cầu.', '[{"chinese":"海关申报","pinyin":"hǎiguān shēnbào","meaning_vi":"khai báo hải quan"},{"chinese":"价值","pinyin":"jiàzhí","meaning_vi":"trị giá"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-df9eaa419fd87725f3a4d1f0.mp3', 77),
    ('请问进口关税的具体税率是多少？', 'Qǐngwèn jìnkǒu guānshuì de jùtǐ shuìlǜ shì duōshǎo?', 'Xin hỏi mức thuế nhập khẩu cụ thể là bao nhiêu?', '[{"chinese":"进口关税","pinyin":"jìnkǒu guānshuì","meaning_vi":"thuế nhập khẩu"},{"chinese":"税率","pinyin":"shuìlǜ","meaning_vi":"mức thuế"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-56a80288e814c1263e4b6a30.mp3', 78),
    ('请尽快提交完整的海关申报单证材料。', 'Qǐng jǐnkuài tíjiāo wánzhěng de hǎiguān shēnbào dānzhèng cáiliào.', 'Xin vui lòng nộp đầy đủ hồ sơ khai báo hải quan càng sớm càng tốt.', '[{"chinese":"海关申报","pinyin":"hǎiguān shēnbào","meaning_vi":"khai báo hải quan"},{"chinese":"单证","pinyin":"dānzhèng","meaning_vi":"hồ sơ, chứng từ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-229f443cf9553909eaafbd1b.mp3', 79),
    ('请提供补充文件以配合海关的进一步审查。', 'Qǐng tígōng bǔchōng wénjiàn yǐ pèihé hǎiguān de jìnyībù shěnchá.', 'Vui lòng cung cấp tài liệu bổ sung để phối hợp với kiểm tra thêm của hải quan.', '[{"chinese":"补充文件","pinyin":"bǔchōng wénjiàn","meaning_vi":"tài liệu bổ sung"},{"chinese":"审查","pinyin":"shěnchá","meaning_vi":"kiểm tra, thẩm tra"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-c50d522b803eca8240f31c03.mp3', 80),
    ('请通知我们参加海关的现场查验和协调。', 'Qǐng tōngzhī wǒmen cānjiā hǎiguān de xiànchǎng cháyàn hé xiétiáo.', 'Xin thông báo cho chúng tôi tham gia kiểm hóa thực tế và phối hợp với hải quan.', '[{"chinese":"现场查验","pinyin":"xiànchǎng cháyàn","meaning_vi":"kiểm hóa thực tế"},{"chinese":"协调","pinyin":"xiétiáo","meaning_vi":"phối hợp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-71ae9b2bd593ca9d50c01267.mp3', 81),
    ('请准备海关所需的解释说明材料以免申报差异。', 'Qǐng zhǔnbèi hǎiguān suǒ xū de jiěshì shuōmíng cáiliào yǐ miǎn shēnbào chāyì.', 'Vui lòng chuẩn bị tài liệu giải trình cho hải quan để tránh sự chênh lệch khai báo.', '[{"chinese":"解释说明","pinyin":"jiěshì shuōmíng","meaning_vi":"giải trình, giải thích"},{"chinese":"申报差异","pinyin":"shēnbào chāyì","meaning_vi":"chênh lệch khai báo"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-f906f49fa31ff7baf3769743.mp3', 82),
    ('请提前申报限制进口商品的相关许可证。', 'Qǐng tíqián shēnbào xiànzhì jìnkǒu shāngpǐn de xiāngguān xǔkězhèng.', 'Vui lòng khai báo trước giấy phép nhập khẩu hàng hóa hạn chế.', '[{"chinese":"限制进口","pinyin":"xiànzhì jìnkǒu","meaning_vi":"hạn chế nhập khẩu"},{"chinese":"许可证","pinyin":"xǔkězhèng","meaning_vi":"giấy phép"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-040795d8fc63e6fb98f7e57d.mp3', 83),
    ('请实时跟进货物通关状态并反馈最新信息。', 'Qǐng shíshí gēnjìn huòwù tōngguān zhuàngtài bìng fǎnkuì zuìxīn xìnxī.', 'Vui lòng theo dõi trạng thái thông quan hàng hóa và phản hồi thông tin mới nhất.', '[{"chinese":"通关状态","pinyin":"tōngguān zhuàngtài","meaning_vi":"trạng thái thông quan"},{"chinese":"反馈","pinyin":"fǎnkuì","meaning_vi":"phản hồi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-081294fa4e13857fffe645ee.mp3', 84),
    ('请将海关放行通知及时发送给我们确认。', 'Qǐng jiāng hǎiguān fàngxíng tōngzhī jíshí fāsòng gěi wǒmen quèrèn.', 'Vui lòng gửi thông báo giải phóng hàng của hải quan kịp thời cho chúng tôi xác nhận.', '[{"chinese":"放行通知","pinyin":"fàngxíng tōngzhī","meaning_vi":"thông báo giải phóng hàng"},{"chinese":"及时","pinyin":"jíshí","meaning_vi":"kịp thời"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-419744b8724111f9ddf680e6.mp3', 85),
    ('请确认货物的HS编码是否符合最新海关目录。', 'Qǐng quèrèn huòwù de HS biānmǎ shìfǒu fúhé zuìxīn hǎiguān mùlù.', 'Vui lòng xác nhận mã HS của hàng hóa có phù hợp với danh mục hải quan mới nhất hay không.', '[{"chinese":"HS编码","pinyin":"HS biānmǎ","meaning_vi":"mã HS"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-d14608aec05089e5265f2135.mp3', 86),
    ('请核实所报关价以避免低报或虚报风险。', 'Qǐng héshí suǒ bào guānjià yǐ bìmiǎn dī bào huò xū bào fēngxiǎn.', 'Vui lòng kiểm tra lại trị giá khai báo để tránh rủi ro khai thấp hoặc khai sai.', '[{"chinese":"报关价","pinyin":"bào guānjià","meaning_vi":"trị giá khai báo hải quan"},{"chinese":"风险","pinyin":"fēngxiǎn","meaning_vi":"rủi ro"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-ce33427b4b1debb3fca2b830.mp3', 87),
