    ('请随时保持与海关代理的联系，确保沟通顺畅。', 'Qǐng suíshí bǎochí yǔ hǎiguān dàilǐ de liánxì, quèbǎo gōutōng shùnchàng.', 'Vui lòng giữ liên lạc thường xuyên với đại lý hải quan để đảm bảo thông suốt.', '[{"chinese":"海关代理","pinyin":"hǎiguān dàilǐ","meaning_vi":"đại lý hải quan"},{"chinese":"沟通","pinyin":"gōutōng","meaning_vi":"giao tiếp, thông suốt"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-5266786157a24f7489067177.mp3', 90),
    ('如遇海关扣押，请及时提交申诉申请并配合调查。', 'Rú yù hǎiguān kòuyā, qǐng jíshí tíjiāo shēnsù shēnqǐng bìng pèihé diàochá.', 'Nếu gặp tình trạng bị hải quan giữ hàng, xin kịp thời nộp đơn khiếu nại và phối hợp điều tra.', '[{"chinese":"扣押","pinyin":"kòuyā","meaning_vi":"giữ hàng, tạm giữ"},{"chinese":"申诉","pinyin":"shēnsù","meaning_vi":"khiếu nại, kháng cáo"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-00e8f70594a07176d414c279.mp3', 91),
    ('请检查所有发票和装箱单是否与申报一致。', 'Qǐng jiǎnchá suǒyǒu fāpiào hé zhuāngxiāng dān shìfǒu yǔ shēnbào yīzhì.', 'Vui lòng kiểm tra xem tất cả hóa đơn và phiếu đóng gói có thống nhất với khai báo hay không.', '[{"chinese":"发票","pinyin":"fāpiào","meaning_vi":"hóa đơn"},{"chinese":"装箱单","pinyin":"zhuāngxiāng dān","meaning_vi":"phiếu đóng gói, packing list"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-cfb806e35ba4a630424c8aef.mp3', 92),
    ('请确定所有单证均已签字盖章确保有效性。', 'Qǐng quèdìng suǒyǒu dānzhèng jūn yǐ qiānzì gàizhāng quèbǎo yǒuxiàoxìng.', 'Vui lòng xác nhận tất cả chứng từ đã được ký và đóng dấu để đảm bảo hiệu lực.', '[{"chinese":"单证","pinyin":"dānzhèng","meaning_vi":"chứng từ, hồ sơ"},{"chinese":"签字盖章","pinyin":"qiānzì gàizhāng","meaning_vi":"ký tên và đóng dấu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-36132a8761e2539918ffc9e6.mp3', 93),
    ('请提供货物的原产地证明以便海关审查。', 'Qǐng tígōng huòwù de yuánchǎndì zhèngmíng yǐbiàn hǎiguān shěnchá.', 'Vui lòng cung cấp chứng nhận xuất xứ hàng hóa để hải quan thẩm tra.', '[{"chinese":"原产地证明","pinyin":"yuánchǎndì zhèngmíng","meaning_vi":"chứng nhận xuất xứ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-d77d11c195d8a4921f068e00.mp3', 94),
    ('请确认进口许可证在货物到港前已获批准。', 'Qǐng quèrèn jìnkǒu xǔkězhèng zài huòwù dàogǎng qián yǐ huò pīzhǔn.', 'Vui lòng xác nhận giấy phép nhập khẩu đã được phê duyệt trước khi hàng đến cảng.', '[{"chinese":"进口许可证","pinyin":"jìnkǒu xǔkězhèng","meaning_vi":"giấy phép nhập khẩu"},{"chinese":"批准","pinyin":"pīzhǔn","meaning_vi":"phê duyệt"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-b72d29eae17a9866087605da.mp3', 95),
    ('请核对检疫证书是否符合最新进口标准。', 'Qǐng héduì jiǎnyì zhèngshū shìfǒu fúhé zuìxīn jìnkǒu biāozhǔn.', 'Vui lòng kiểm tra xem chứng nhận kiểm dịch có đáp ứng tiêu chuẩn nhập khẩu mới nhất hay không.', '[{"chinese":"检疫证书","pinyin":"jiǎnyì zhèngshū","meaning_vi":"chứng nhận kiểm dịch"},{"chinese":"进口标准","pinyin":"jìnkǒu biāozhǔn","meaning_vi":"tiêu chuẩn nhập khẩu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-a91cdb2e770aaeffb7f2d6ea.mp3', 96),
    ('请在清关前核查所有单据的复印件是否齐全。', 'Qǐng zài qīngguān qián héchá suǒyǒu dānjù de fùyìnjiàn shìfǒu qíquán.', 'Vui lòng đối chiếu trước khi làm thủ tục hải quan xem các bản sao chứng từ có đầy đủ hay không.', '[{"chinese":"清关","pinyin":"qīngguān","meaning_vi":"thông quan"},{"chinese":"复印件","pinyin":"fùyìnjiàn","meaning_vi":"bản sao"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-21fa62f2f8964656a5427a41.mp3', 97),
    ('请签字盖章后将所有单证扫描并发送给我方。', 'Qǐng qiānzì gàizhāng hòu jiāng suǒyǒu dānzhèng sǎomiáo bìng fāsòng gěi wǒ fāng.', 'Vui lòng ký và đóng dấu rồi quét tất cả chứng từ gửi cho chúng tôi.', '[{"chinese":"扫描","pinyin":"sǎomiáo","meaning_vi":"quét (tài liệu)"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-f2f5f7365d63c39c9e18bd88.mp3', 98),
    ('如需修改申报内容，请提供具体变更说明。', 'Rú xū xiūgǎi shēnbào nèiróng, qǐng tígōng jùtǐ biàngēng shuōmíng.', 'Nếu cần sửa đổi nội dung khai báo, vui lòng cung cấp giải thích cụ thể về thay đổi.', '[{"chinese":"修改","pinyin":"xiūgǎi","meaning_vi":"sửa đổi"},{"chinese":"申报内容","pinyin":"shēnbào nèiróng","meaning_vi":"nội dung khai báo"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-fd0a5e89bbc6942d107c126a.mp3', 99),
    ('请认真核对采购合同与报关单据是否一致。', 'Qǐng rènzhēn héduì cǎigòu hétonɡ yǔ bàoguān dānjù shìfǒu yīzhì.', 'Vui lòng kiểm tra kỹ xem hợp đồng mua hàng có khớp với chứng từ khai báo hải quan không.', '[{"chinese":"采购合同","pinyin":"cǎigòu hétong","meaning_vi":"hợp đồng mua hàng"},{"chinese":"报关单据","pinyin":"bàoguān dānjù","meaning_vi":"chứng từ khai báo hải quan"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-cf1cce82fdd27147852dc2b1.mp3', 100),
    ('请您确认本批货物的入库时间和仓库位置。', 'Qǐng nín quèrèn běn pī huòwù de rùkù shíjiān hé cāngkù wèizhì.', 'Vui lòng xác nhận thời gian nhập kho và vị trí kho hàng của lô hàng này.', '[{"chinese":"入库","pinyin":"rùkù","meaning_vi":"nhập kho"},{"chinese":"仓库","pinyin":"cāngkù","meaning_vi":"kho hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-633092064ba1d87fe3508432.mp3', 101),
    ('请将出库单提前发送以便我们核对货物信息。', 'Qǐng jiāng chūkù dān tíqián fāsòng yǐbiàn wǒmen héduì huòwù xìnxī.', 'Vui lòng gửi phiếu xuất kho trước để chúng tôi kiểm tra thông tin hàng hóa.', '[{"chinese":"出库单","pinyin":"chūkù dān","meaning_vi":"phiếu xuất kho"},{"chinese":"核对","pinyin":"héduì","meaning_vi":"kiểm tra, đối chiếu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-72e7ed1e348eb68bd6f84ca0.mp3', 102),
    ('我们需要安排月底进行库存盘点，请协助准备清单。', 'Wǒmen xūyào ānpái yuèdǐ jìnxíng kùcún pándiǎn, qǐng xiézhù zhǔnbèi qīngdān.', 'Chúng tôi cần sắp xếp kiểm kê kho vào cuối tháng, xin hỗ trợ chuẩn bị bảng kê.', '[{"chinese":"库存盘点","pinyin":"kùcún pándiǎn","meaning_vi":"kiểm kê tồn kho"},{"chinese":"清单","pinyin":"qīngdān","meaning_vi":"bảng kê"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-5d2b1828fa8ae63e690a5b89.mp3', 103),
    ('请确认包装规格和数量符合合同要求。', 'Qǐng quèrèn bāozhuāng guīgé hé shùliàng fúhé hé​tóng yāoqiú.', 'Xin vui lòng xác nhận quy cách và số lượng bao bì phù hợp với yêu cầu hợp đồng.', '[{"chinese":"包装规格","pinyin":"bāozhuāng guīgé","meaning_vi":"quy cách đóng gói"},{"chinese":"合同","pinyin":"hé​tóng","meaning_vi":"hợp đồng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-c8a44f289b44e971ec054539.mp3', 104),
    ('货物应贴有清晰的运输标签以确保追踪方便。', 'Huòwù yīng tiē yǒu qīngxī de yùnshū biāoqiān yǐ quèbǎo zhuīzōng fāngbiàn.', 'Hàng hóa cần được dán nhãn vận chuyển rõ ràng để đảm bảo việc theo dõi thuận tiện.', '[{"chinese":"运输标签","pinyin":"yùnshū biāoqiān","meaning_vi":"nhãn vận chuyển"},{"chinese":"追踪","pinyin":"zhuīzōng","meaning_vi":"theo dõi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-e38c9d114ade739814e86b11.mp3', 105),
    ('请尽快确认货物在运输公司的订舱信息。', 'Qǐng jǐnkuài quèrèn huòwù zài yùnshū gōngsī de dìngcāng xìnxī.', 'Vui lòng nhanh chóng xác nhận thông tin đặt chỗ vận tải cho hàng hóa.', '[{"chinese":"订舱","pinyin":"dìngcāng","meaning_vi":"đặt chỗ vận tải (tàu, máy bay)"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-a4c09ab2718dbfd1a166350f.mp3', 106),
    ('请提供最新的航班时间表以便安排取货。', 'Qǐng tígōng zuìxīn de hángbān shíjiān biǎo yǐbiàn ānpái qǔ huò.', 'Vui lòng cung cấp lịch chuyến bay mới nhất để sắp xếp lấy hàng.', '[{"chinese":"航班时间表","pinyin":"hángbān shíjiān biǎo","meaning_vi":"lịch chuyến bay"},{"chinese":"安排","pinyin":"ānpái","meaning_vi":"sắp xếp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-84c1add3360153a722c5e514.mp3', 107),
    ('请您随时更新货物的运输跟踪状态。', 'Qǐng nín suíshí gēngxīn huòwù de yùnshū gēnzōng zhuàngtài.', 'Vui lòng cập nhật thường xuyên trạng thái theo dõi vận tải hàng hóa.', '[{"chinese":"运输跟踪","pinyin":"yùnshū gēnzōng","meaning_vi":"theo dõi vận tải"},{"chinese":"状态","pinyin":"zhuàngtài","meaning_vi":"trạng thái"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-83e19543a706298bdec0923b.mp3', 108),
    ('请确认提货时间和提货地点以便安排提货。', 'Qǐng quèrèn tí huò shíjiān hé tí huò dìdiǎn yǐbiàn ānpái tí huò.', 'Vui lòng xác nhận thời gian và địa điểm lấy hàng để bố trí lấy hàng.', '[{"chinese":"提货时间","pinyin":"tí huò shíjiān","meaning_vi":"thời gian lấy hàng"},{"chinese":"提货地点","pinyin":"tí huò dìdiǎn","meaning_vi":"địa điểm lấy hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-a74f3cf4575e66128d062335.mp3', 109),
    ('收货地址请再次确认以确保无误。', 'Shōu huò dìzhǐ qǐng zàicì quèrèn yǐ quèbǎo wúwù.', 'Vui lòng xác nhận lại địa chỉ giao hàng để đảm bảo không sai sót.', '[{"chinese":"收货地址","pinyin":"shōu huò dìzhǐ","meaning_vi":"địa chỉ giao hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-38276af93717f5a1d6bb4ef7.mp3', 110),
    ('请在交货时签收并填写交接记录。', 'Qǐng zài jiāohuò shí qiānshōu bìng tiánxiě jiāojiē jìlù.', 'Vui lòng ký nhận và ghi chép biên bản bàn giao lúc giao hàng.', '[{"chinese":"签收","pinyin":"qiānshōu","meaning_vi":"ký nhận"},{"chinese":"交接记录","pinyin":"jiāojiē jìlù","meaning_vi":"biên bản bàn giao"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-f376d9bbb82c32a4f798d8d9.mp3', 111),
    ('请确认货物包装是否符合运输安全标准。', 'Qǐng quèrèn huòwù bāozhuāng shìfǒu fúhé yùnshū ānquán biāozhǔn.', 'Vui lòng xác nhận bao bì hàng hóa có đáp ứng tiêu chuẩn an toàn vận tải không.', '[{"chinese":"包装","pinyin":"bāozhuāng","meaning_vi":"đóng gói, bao bì"},{"chinese":"运输安全标准","pinyin":"yùnshū ānquán biāozhǔn","meaning_vi":"tiêu chuẩn an toàn vận tải"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-96740fd333743af7fc8d8f51.mp3', 112),
    ('请及时通知我们航运的最新动态和到港时间。', 'Qǐng jíshí tōngzhī wǒmen hángyùn de zuìxīn dòngtài hé dào gǎng shíjiān.', 'Vui lòng thông báo kịp thời cho chúng tôi thông tin vận tải đường biển mới nhất và thời gian đến cảng.', '[{"chinese":"航运","pinyin":"hángyùn","meaning_vi":"vận tải hàng hải"},{"chinese":"到港时间","pinyin":"dào gǎng shíjiān","meaning_vi":"thời gian đến cảng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-95e17d037e184d1c693f6882.mp3', 113),
    ('遇到货物损坏请立即联系并提出理赔申请。', 'Yùdào huòwù sǔnhuài qǐng lìjí liánxì bìng tíchū lǐpéi shēnqǐng.', 'Nếu gặp hàng hóa bị hư hỏng, xin liên hệ ngay và nộp đơn yêu cầu bồi thường.', '[{"chinese":"货物损坏","pinyin":"huòwù sǔnhuài","meaning_vi":"hàng hóa hư hỏng"},{"chinese":"理赔申请","pinyin":"lǐpéi shēnqǐng","meaning_vi":"đơn yêu cầu bồi thường"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-37e3ca64dc4be60768286af5.mp3', 114),
    ('请确认货物堆放的位置符合安全规范。', 'Qǐng quèrèn huòwù duīfàng de wèizhì fúhé ānquán guīfàn.', 'Vui lòng xác nhận vị trí chất hàng phù hợp với quy định an toàn.', '[{"chinese":"堆放","pinyin":"duīfàng","meaning_vi":"xếp chồng, chất đống"},{"chinese":"安全规范","pinyin":"ānquán guīfàn","meaning_vi":"quy định an toàn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-ed86a27084751cb72aad47a0.mp3', 115),
    ('请提供货物的详细尺寸和重量信息。', 'Qǐng tígōng huòwù de xiángxì chǐcùn hé zhòngliàng xìnxī.', 'Xin cung cấp thông tin chi tiết về kích thước và trọng lượng hàng hóa.', '[{"chinese":"尺寸","pinyin":"chǐcùn","meaning_vi":"kích thước"},{"chinese":"重量","pinyin":"zhòngliàng","meaning_vi":"trọng lượng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-ce1298760ed5d4eee50fd96b.mp3', 116),
    ('请确认装卸时间避免与仓库操作冲突。', 'Qǐng quèrèn zhuāngxiè shíjiān bìmiǎn yǔ cāngkù cāozuò chōngtú.', 'Vui lòng xác nhận thời gian bốc dỡ để tránh xung đột với hoạt động kho bãi.', '[{"chinese":"装卸时间","pinyin":"zhuāngxiè shíjiān","meaning_vi":"thời gian bốc dỡ"},{"chinese":"仓库操作","pinyin":"cāngkù cāozuò","meaning_vi":"hoạt động kho hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-de6f3d7c34e0c51606a5a4f2.mp3', 117),
    ('请确认运输合同中的交货地点和方式。', 'Qǐng quèrèn yùnshū hétóng zhōng de jiāohuò dìdiǎn hé fāngshì.', 'Vui lòng xác nhận địa điểm và phương thức giao hàng trong hợp đồng vận tải.', '[{"chinese":"运输合同","pinyin":"yùnshū hétóng","meaning_vi":"hợp đồng vận tải"},{"chinese":"交货地点","pinyin":"jiāohuò dìdiǎn","meaning_vi":"địa điểm giao hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-08d702390caa2010a81ae35d.mp3', 118),
    ('请核对提单上的货物描述和数量是否一致。', 'Qǐng héduì tídān shàng de huòwù miáoshù hé shùliàng shìfǒu yīzhì.', 'Vui lòng đối chiếu mô tả và số lượng hàng hóa trên vận đơn có đúng nhau không.', '[{"chinese":"提单","pinyin":"tídān","meaning_vi":"vận đơn"},{"chinese":"描述","pinyin":"miáoshù","meaning_vi":"mô tả"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-9599ac8f89b616b5492c9f82.mp3', 119),
    ('请提供详细的装箱清单以便海关核查。', 'Qǐng tígōng xiángxì de zhuāngxiāng qīngdān yǐbiàn hǎiguān héchá.', 'Xin cung cấp bảng kê chi tiết đóng kiện để hải quan kiểm tra.', '[{"chinese":"装箱清单","pinyin":"zhuāngxiāng qīngdān","meaning_vi":"bảng kê đóng gói"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-0cf32489265cde092583a0a0.mp3', 120),
    ('请安排仓库人员准备货物的装卸工作。', 'Qǐng ānpái cāngkù rényuán zhǔnbèi huòwù de zhuāngxiè gōngzuò.', 'Vui lòng sắp xếp nhân viên kho chuẩn bị công việc xếp dỡ hàng hóa.', '[{"chinese":"装卸","pinyin":"zhuāngxiè","meaning_vi":"xếp dỡ hàng hóa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-69a642472fb3129dce687996.mp3', 121),
    ('货物包装必须防潮防震以保证运输安全。', 'Huòwù bāozhuāng bìxū fáng cháo fáng zhèn yǐ bǎozhèng yùnshū ānquán.', 'Bao bì hàng hóa phải chống ẩm và chống sốc để đảm bảo an toàn vận tải.', '[{"chinese":"防潮","pinyin":"fáng cháo","meaning_vi":"chống ẩm"},{"chinese":"防震","pinyin":"fáng zhèn","meaning_vi":"chống sốc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-04aa6231df3c006a1ecc352e.mp3', 122),
    ('请确认卸货地点的接收能力和时间安排。', 'Qǐng quèrèn xiè huò dìdiǎn de jiēshōu nénglì hé shíjiān ānpái.', 'Vui lòng xác nhận khả năng tiếp nhận và lịch trình tại địa điểm dỡ hàng.', '[{"chinese":"卸货地点","pinyin":"xiè huò dìdiǎn","meaning_vi":"địa điểm dỡ hàng"},{"chinese":"接收能力","pinyin":"jiēshōu nénglì","meaning_vi":"khả năng tiếp nhận"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-ea9d372fd983d7e893729cf5.mp3', 123),
    ('请提供货物装运状态的每日更新报告。', 'Qǐng tígōng huòwù zhuāngyùn zhuàngtài de měi rì gēngxīn bàogào.', 'Xin cung cấp báo cáo cập nhật hàng ngày về trạng thái vận chuyển hàng hóa.', '[{"chinese":"装运状态","pinyin":"zhuāngyùn zhuàngtài","meaning_vi":"trạng thái vận chuyển"},{"chinese":"更新报告","pinyin":"gēngxīn bàogào","meaning_vi":"báo cáo cập nhật"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-5e59d7c296bb299e6b471e23.mp3', 124),
    ('请核实货物的堆码方式是否符合仓库存储规定。', 'Qǐng héshí huòwù de duī mǎ fāngshì shìfǒu fúhé cāngkù cúnchú guīdìng.', 'Vui lòng kiểm tra cách xếp chồng hàng có phù hợp với quy định lưu kho không.', '[{"chinese":"堆码方式","pinyin":"duī mǎ fāngshì","meaning_vi":"cách xếp chồng"},{"chinese":"仓库存储","pinyin":"cāngkù cúnchú","meaning_vi":"lưu kho"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-be0f06de3ddfb412a5a86c0a.mp3', 125),
    ('货物预计晚于约定交货时间，请确认最新到货计划。', 'Huòwù yùjì wǎn yú yuēdìng jiāohuò shíjiān, qǐng quèdìng zuìxīn dàohuò jìhuà.', 'Hàng hóa dự kiến giao trễ hơn thời gian đã thỏa thuận, xin vui lòng xác nhận kế hoạch giao hàng mới nhất.', '[{"chinese":"交货时间","pinyin":"jiāohuò shíjiān","meaning_vi":"thời gian giao hàng"},{"chinese":"到货计划","pinyin":"dàohuò jìhuà","meaning_vi":"kế hoạch nhận hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-c9b6a653c46187e0f25e9939.mp3', 126),
    ('本批货物实际数量少于订单，请核实并反馈缺货明细。', 'Běn pī huòwù shíjì shùliàng shǎo yú dìngdān, qǐng héshí bìng fǎnkuì quē huò míngxì.', 'Số lượng hàng thực tế lô này ít hơn đơn đặt hàng, xin vui lòng kiểm tra và phản hồi chi tiết thiếu hàng.', '[{"chinese":"实际数量","pinyin":"shíjì shùliàng","meaning_vi":"số lượng thực tế"},{"chinese":"缺货","pinyin":"quē huò","meaning_vi":"thiếu hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-6c2e3d43dd1add3281809281.mp3', 127),
    ('收到的货物与合同规格不符，请核对并说明差异原因。', 'Shōudào de huòwù yǔ hétonɡ ɡuīɡé bù fú, qǐnɡ héduì bìnɡ shuōmínɡ chāyì yuányīn.', 'Hàng hóa nhận được không đúng quy cách hợp đồng, xin vui lòng kiểm tra và giải thích lý do chênh lệch.', '[{"chinese":"规格","pinyin":"guīgé","meaning_vi":"quy cách"},{"chinese":"差异原因","pinyin":"chāyì yuányīn","meaning_vi":"lý do chênh lệch"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-8cbb89a9bff137df581010a2.mp3', 128),
    ('货物在运输途中丢失，请及时提供遗失证明和相关报告。', 'Huòwù zài yùnshū túzhōnɡ diūshī, qǐnɡ jíshí tíɡōnɡ yíshī zhènɡmínɡ hé xiānɡɡuān bàogào.', 'Hàng hóa bị mất trong quá trình vận chuyển, vui lòng kịp thời cung cấp chứng minh mất hàng và báo cáo liên quan.', '[{"chinese":"运输途中","pinyin":"yùnshū túzhōng","meaning_vi":"quá trình vận chuyển"},{"chinese":"遗失证明","pinyin":"yíshī zhèngmíng","meaning_vi":"chứng minh mất hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-88c8fbadb7629051cdc90d25.mp3', 129),
    ('部分货物包装破损，请拍照并保存以便理赔使用。', 'Bùfen huòwù bāozhuānɡ pòsǔn, qǐnɡ pāizhào bìnɡ bǎocún yǐbiàn lǐpéi shǐyònɡ.', 'Phần bao bì hàng hóa bị hư hỏng, xin chụp ảnh và lưu giữ để sử dụng trong việc bồi thường.', '[{"chinese":"包装破损","pinyin":"bāozhuānɡ pòsǔn","meaning_vi":"bao bì hư hỏng"},{"chinese":"理赔","pinyin":"lǐpéi","meaning_vi":"bồi thường"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-efd31ab3f3133c9e4cb23703.mp3', 130),
    ('请协助修改装箱单中错误的商品信息以符合实物情况。', 'Qǐnɡ xiézhù xiūɡǎi zhuānɡxiānɡ dān zhōnɡ cuòwù de shānɡpǐn xìnxī yǐ fúhé shíwù qínɡkuànɡ.', 'Xin phối hợp sửa thông tin hàng hóa sai lệch trên phiếu đóng gói để phù hợp thực tế.', '[{"chinese":"装箱单","pinyin":"zhuānɡxiānɡ dān","meaning_vi":"phiếu đóng gói"},{"chinese":"错误","pinyin":"cuòwù","meaning_vi":"sai sót"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-2c51a0431a6f502dee4292dd.mp3', 131),
    ('请说明因延迟卸货产生的额外仓储费用明细。', 'Qǐnɡ shuōmínɡ yīn yánchí xièhù chǎnshēnɡ de éwài cānɡchǔ fèiyònɡ mínɡxì.', 'Xin vui lòng giải thích chi tiết các chi phí lưu kho phát sinh do chậm dỡ hàng.', '[{"chinese":"仓储费用","pinyin":"cānɡchǔ fèiyònɡ","meaning_vi":"chi phí lưu kho"},{"chinese":"额外","pinyin":"éwài","meaning_vi":"thêm, ngoài dự kiến"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-d4a80a2c9e44260869258d59.mp3', 132),
    ('请提供货物损坏的照片和现场记录以便申请赔偿。', 'Qǐnɡ tíɡōnɡ huòwù sǔnhuài de zhàopiàn hé xiànchǎnɡ jìlù yǐbiàn shēnqǐnɡ péichánɡ.', 'Xin cung cấp ảnh và biên bản hiện trường hàng hóa bị hư hỏng để làm hồ sơ yêu cầu bồi thường.', '[{"chinese":"损坏","pinyin":"sǔnhuài","meaning_vi":"hư hỏng"},{"chinese":"赔偿","pinyin":"péichánɡ","meaning_vi":"bồi thường"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-443a1ca2b0906a362f9fc76a.mp3', 133),
    ('已收到费用通知，请确认滞箱费的具体计算方式。', 'Yǐ shōudào fèiyònɡ tōnɡzhī, qǐnɡ quèrèn zhì xiānɡ fèi de jùtǐ jìsuàn fānɡshì.', 'Đã nhận được thông báo phí, xin xác nhận phương thức tính phí lưu container cụ thể.', '[{"chinese":"滞箱费","pinyin":"zhì xiānɡ fèi","meaning_vi":"phí lưu container"},{"chinese":"计算方式","pinyin":"jìsuàn fānɡshì","meaning_vi":"phương thức tính toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-31451a4632d61b1ea540f9cf.mp3', 134),
    ('为便于处理投诉，请提供相关证据资料和事件详细说明。', 'Wèi biànyú chǔlǐ tóusù, qǐnɡ tíɡōnɡ xiānɡɡuān zhènɡjù zīliào hé shìjiàn xiángxì shuōmínɡ.', 'Để thuận tiện xử lý khiếu nại, vui lòng cung cấp tài liệu chứng cứ liên quan và mô tả chi tiết sự việc.', '[{"chinese":"投诉","pinyin":"tóusù","meaning_vi":"khiếu nại"},{"chinese":"证据资料","pinyin":"zhènɡjù zīliào","meaning_vi":"tài liệu chứng cứ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-86ddab2a09f2018e1f2b6ff7.mp3', 135),
    ('异常情况已记录，请安排人员尽快编写调查报告。', 'Yìchánɡ qínɡkuànɡ yǐ jìlù, qǐnɡ ānpái rényuán jǐnkuài biānxiě diàochá bàogào.', 'Tình trạng bất thường đã được ghi nhận, xin sắp xếp nhân viên nhanh chóng lập báo cáo điều tra.', '[{"chinese":"异常","pinyin":"yìchánɡ","meaning_vi":"bất thường"},{"chinese":"调查报告","pinyin":"diàochá bàogào","meaning_vi":"báo cáo điều tra"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-e5e305104e387e7c1b59ccab.mp3', 136),
    ('请确认收货后及时向我们反馈任何差异或问题。', 'Qǐnɡ quèrèn shōuhuò hòu jíshí xiànɡ wǒmen fǎnkuì rènhé chāyì huò wèntí.', 'Xin xác nhận sau khi nhận hàng kịp thời phản hồi cho chúng tôi bất kỳ sự chênh lệch hoặc vấn đề nào.', '[{"chinese":"差异","pinyin":"chāyì","meaning_vi":"sự khác biệt"},{"chinese":"反馈","pinyin":"fǎnkuì","meaning_vi":"phản hồi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-f29a0ecf79ba287aa749a9ea.mp3', 137),
    ('货物异常，请尽快提供异常情况的详细说明和相关资料。', 'Huòwù yìchánɡ, qǐnɡ jǐnkuài tíɡōnɡ yìchánɡ qínɡkuànɡ de xiángxì shuōmínɡ hé xiānɡɡuān zīliào.', 'Hàng hóa có sự cố khác thường, xin nhanh chóng cung cấp mô tả chi tiết và tài liệu liên quan.', '[{"chinese":"异常情况","pinyin":"yìchánɡ qínɡkuànɡ","meaning_vi":"tình trạng bất thường"},{"chinese":"详细说明","pinyin":"xiángxì shuōmínɡ","meaning_vi":"giải thích chi tiết"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-5321a4c5506b76cee726ffd2.mp3', 138),
    ('为保证赔偿流程顺利，请提供正式的理赔申请和支持文件。', 'Wèi bǎozhènɡ péichánɡ liúchéng shùnlì, qǐnɡ tíɡōnɡ zhènɡshì de lǐpéi shēnqǐnɡ hé zhīchí wénjiàn.', 'Để đảm bảo quy trình bồi thường thuận lợi, xin cung cấp đơn yêu cầu và các tài liệu hỗ trợ chính thức.', '[{"chinese":"赔偿流程","pinyin":"péichánɡ liúchéng","meaning_vi":"quy trình bồi thường"},{"chinese":"理赔申请","pinyin":"lǐpéi shēnqǐnɡ","meaning_vi":"đơn yêu cầu bồi thường"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-1e0842a9f603042dbfbc9cb0.mp3', 139),
    ('贵方对本次货物损失承担责任，请尽快处理理赔事宜。', 'Guì fānɡ duì běn cì huòwù sǔnshī chénɡdān zérèn, qǐnɡ jǐnkuài chǔlǐ lǐpéi shìyí.', 'Phía quý bên chịu trách nhiệm về tổn thất hàng hóa lần này, xin nhanh chóng giải quyết vấn đề bồi thường.', '[{"chinese":"承担责任","pinyin":"chénɡdān zérèn","meaning_vi":"chịu trách nhiệm"},{"chinese":"理赔事宜","pinyin":"lǐpéi shìyí","meaning_vi":"vấn đề bồi thường"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-50558144550256477a6c9635.mp3', 140),
    ('请持续关注理赔进度，并及时通知我们处理结果。', 'Qǐnɡ chíxù ɡuānzhù lǐpéi jìn dù, bìnɡ jíshí tōnɡzhī wǒmen chǔlǐ jiéɡuǒ.', 'Xin tiếp tục theo dõi tiến độ bồi thường và kịp thời thông báo cho chúng tôi kết quả xử lý.', '[{"chinese":"理赔进度","pinyin":"lǐpéi jìn dù","meaning_vi":"tiến độ bồi thường"},{"chinese":"处理结果","pinyin":"chǔlǐ jiéɡuǒ","meaning_vi":"kết quả xử lý"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-9cce79201c7c31a268435411.mp3', 141),
    ('货物包装箱破裂，影响运输安全，请确认后续处理方案。', 'Huòwù bāozhuānɡ xiānɡ pòliè, yǐnɡxiǎnɡ yùnshū ānquán, qǐnɡ quèrèn hòuxù chǔlǐ fānɡàn.', 'Thùng bao bì hàng hóa bị rách, ảnh hưởng tới an toàn vận chuyển, xin xác nhận phương án xử lý tiếp theo.', '[{"chinese":"包装箱","pinyin":"bāozhuānɡ xiānɡ","meaning_vi":"thùng bao bì"},{"chinese":"运输安全","pinyin":"yùnshū ānquán","meaning_vi":"an toàn vận chuyển"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-c2eb99d0060dd9c52297199f.mp3', 142),
    ('发现箱内货物标签错误，请及时更正并反馈。', 'Fāxiàn xiānɡ nèi huòwù biāoqiān cuòwù, qǐnɡ jíshí gēnɡzhènɡ bìnɡ fǎnkuì.', 'Phát hiện nhãn hàng trong thùng bị sai, xin kịp thời chỉnh sửa và phản hồi.', '[{"chinese":"标签错误","pinyin":"biāoqiān cuòwù","meaning_vi":"nhãn sai sót"},{"chinese":"更正","pinyin":"gēnɡzhènɡ","meaning_vi":"sửa lại"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-603c0ecc008d07472ddd1552.mp3', 143),
    ('迟延交货导致生产停滞，请尽快解决并提出补救措施。', 'Chíyán jiāohuò dǎozhì shēnɡchǎn tǐnɡzhì, qǐnɡ jǐnkuài jiějué bìnɡ tíchū bǔjiù cuòshī.', 'Giao hàng chậm gây đình trệ sản xuất, xin nhanh chóng xử lý và đề xuất giải pháp khắc phục.', '[{"chinese":"迟延交货","pinyin":"chíyán jiāohuò","meaning_vi":"giao hàng chậm"},{"chinese":"补救措施","pinyin":"bǔjiù cuòshī","meaning_vi":"giải pháp khắc phục"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-3a2cba8a2cd9b5ead06a0383.mp3', 144),
    ('货物短缺部分已报，请及时安排补发并通知货运。', 'Huòwù duǎnquē bùfen yǐ bào, qǐnɡ jíshí ānpái bǔfā bìnɡ tōnɡzhī huòyùn.', 'Phần thiếu hàng đã báo, xin kịp thời sắp xếp bổ sung và thông báo với đơn vị vận tải.', '[{"chinese":"短缺","pinyin":"duǎnquē","meaning_vi":"thiếu hụt"},{"chinese":"补发","pinyin":"bǔfā","meaning_vi":"bổ sung gửi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-6daf045ac0c778b6883c6456.mp3', 145),
    ('装箱单与实际货物不符，请检查并重新提交正确单据。', 'Zhuānɡxiānɡ dān yǔ shíjì huòwù bù fú, qǐnɡ jiǎnchá bìnɡ chóngxīn tíjiāo zhènɡquè dānjù.', 'Phiếu đóng gói không phù hợp với hàng thực tế, xin kiểm tra và nộp lại chứng từ chính xác.', '[{"chinese":"重新提交","pinyin":"chóngxīn tíjiāo","meaning_vi":"nộp lại"},{"chinese":"单据","pinyin":"dānjù","meaning_vi":"chứng từ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-d92b2a194928ead68479d749.mp3', 146),
    ('运输过程中发生损耗，请核算具体损失并提出赔偿要求。', 'Yùnshū ɡuòchénɡ zhōnɡ fāshēng sǔnhào, qǐnɡ hésuàn jùtǐ sǔnshī bìnɡ tíchū péichánɡ yāoqiú.', 'Phát sinh hao hụt trong quá trình vận chuyển, xin tính toán cụ thể tổn thất và đưa ra yêu cầu bồi thường.', '[{"chinese":"运输过程","pinyin":"yùnshū ɡuòchénɡ","meaning_vi":"quá trình vận chuyển"},{"chinese":"赔偿要求","pinyin":"péichánɡ yāoqiú","meaning_vi":"yêu cầu bồi thường"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-7d08640c00218ca7cf4e6b50.mp3', 147),
    ('货物包装不符合标准，请确认后立即更换以避免风险。', 'Huòwù bāozhuānɡ bù fúhé biāozhǔn, qǐnɡ quèrèn hòu lìjí ɡēnɡhuàn yǐ bìmiǎn fēnɡxiǎn.', 'Bao bì hàng hóa không đạt tiêu chuẩn, xin xác nhận và thay thế ngay nhằm tránh rủi ro.', '[{"chinese":"包装不符合标准","pinyin":"bāozhuānɡ bù fúhé biāozhǔn","meaning_vi":"bao bì không đạt chuẩn"},{"chinese":"避免风险","pinyin":"bìmiǎn fēnɡxiǎn","meaning_vi":"tránh rủi ro"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-6be2ba7d1da0db7cf42e1b31.mp3', 148),
    ('合同条款未能完全履行，烦请提供延误原因及补救计划。', 'Hétónɡ tiáokuǎn wèinéng wánquán lǚxínɡ, fánqǐnɡ tíɡōnɡ yánwù yuányīn jí bǔjiù jìhuà.', 'Các điều khoản hợp đồng chưa được thực hiện đầy đủ, xin vui lòng cung cấp nguyên nhân chậm trễ và kế hoạch khắc phục.', '[{"chinese":"合同条款","pinyin":"hétónɡ tiáokuǎn","meaning_vi":"điều khoản hợp đồng"},{"chinese":"补救计划","pinyin":"bǔjiù jìhuà","meaning_vi":"kế hoạch khắc phục"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-bad148dc66f612e2436538a3.mp3', 149),
    ('收到运输异常信息，烦请提供详细整改时间表。', 'Shōudào yùnshū yìcháng xìnxī, fánqǐng tígōng xiángxì zhěnggǎi shíjiānbiǎo.', 'Đã nhận thông tin vận chuyển bất thường, vui lòng cung cấp tiến độ khắc phục chi tiết.', '[{"chinese":"运输异常","pinyin":"yùnshū yìcháng","meaning_vi":"sự cố vận chuyển"},{"chinese":"整改时间表","pinyin":"zhěnggǎi shíjiānbiǎo","meaning_vi":"tiến độ khắc phục"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-150-cau/sentence-00456e08e19178f1544d075c.mp3', 150)
) as card(
  sentence_cn, sentence_pinyin, sentence_vi,
  vocab_json, sentence_audio_url, position
)
on conflict (template_deck_id, sentence_cn) do update
set
  sentence_pinyin = excluded.sentence_pinyin,
  sentence_vi = excluded.sentence_vi,
  vocab_json = excluded.vocab_json,
  sentence_audio_url = excluded.sentence_audio_url,
  position = excluded.position;

